-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromeCLGauge.json. Do not edit: change the chain file or ABI and regenerate.
-- Withdraw(address,uint256,uint128)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_cl_gauge__withdraw',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as user,
    reinterpretAsUInt256(reverse(unhex(substring(topic2, 3, 64)))) as token_id,
    toUInt128(reinterpretAsUInt256(reverse(unhex(substring(topic3, 3, 64))))) as liquidity_to_stake
from {{ source('chain_base', 'logs') }}
where topic0 = '0x8903a5b5d08a841e7f68438387f1da20c84dea756379ed37e633ff3854b99b84'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_cl_gauge')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
